ALTER TABLE "ai_jobs" DROP CONSTRAINT "ai_jobs_status_ck";--> statement-breakpoint
ALTER TABLE "ai_jobs" ADD CONSTRAINT "ai_jobs_status_ck" CHECK ("ai_jobs"."status" in ('queued', 'running', 'succeeded', 'failed', 'skipped'));--> statement-breakpoint
-- Data backfill (T3-knowledge): starter description and classification guidance for the 17 seeded subcategories.
-- Matches by key and fills a field only while it is null or blank, so text a person wrote stays. The texts mirror
-- DEFAULT_SUBCATEGORIES in src/contexts/conversations/domain/default-pipeline.ts (a test keeps the two in step).
UPDATE "subcategories" s
SET "description" = CASE WHEN s."description" IS NULL OR btrim(s."description") = '' THEN d.description ELSE s."description" END,
    "classification_guidance" = CASE WHEN s."classification_guidance" IS NULL OR btrim(s."classification_guidance") = '' THEN d.guidance ELSE s."classification_guidance" END
FROM (VALUES
	('information_requested', 'The person asks for product, pricing, feature, integration, or company details before deciding.', 'Pick this when the main ask is for answers or material and the person names no case study, meeting, demo, or trial. A question about price or how something works belongs here. If the reply also asks for a call, prefer Meeting requested.'),
	('case_study', 'The person asks for a customer story, reference, or proof of results.', 'Pick this when the person asks for a case study, a customer example, numbers from a similar company, or a reference call with a customer. A general request for more information belongs under Information requested.'),
	('demo_request', 'The person wants to see the product in action.', 'Pick this when the person asks for a demo, a walkthrough, a product tour, or a recording of the product. If they only ask to talk, pick Meeting requested. If they ask for hands-on access, pick Trial requested.'),
	('meeting_requested', 'The person agrees to talk or asks to book a time.', 'Pick this when the person proposes times, asks for your availability or a calendar link, or says yes to a call you suggested. A reply that only says they are interested, with no mention of a call, belongs under Information requested.'),
	('meeting_no_show', 'A booked meeting passed and the person did not attend.', 'Pick this when the person writes that they missed the meeting or asks to rebook after a missed slot, or when the thread shows a confirmed time that has passed with no attendance. Do not pick it for a person who cancels in advance; that is a new Meeting requested.'),
	('meeting_done', 'The meeting took place and a follow-up is due.', 'Pick this when the thread shows that the call happened and the next message should recap what was discussed, who owns which action, and what comes next. Thanks for your time after a call is a typical signal.'),
	('trial_requested', 'The person wants to start a trial or asks how to get access.', 'Pick this when the person asks to start, activate, or get access to a trial or a sandbox, or asks what the next step to begin is. Once they are already using the trial, pick Trial user.'),
	('trial_user', 'The person already uses the trial and needs help or reports progress.', 'Pick this when a person with an active trial writes about setup, an integration, a feature they tried, an error, or onboarding. A first request for access belongs under Trial requested.'),
	('customer', 'The person is an existing customer, for example a billing, renewal, or account question.', 'Pick this when the sender is already a paying customer and writes about their account, an invoice, a renewal, or support for the product they use. A cold prospect who sounds enthusiastic is not a customer. This subcategory always goes to a person for review.'),
	('do_not_contact', 'The person asks to stop all contact or be removed from outreach.', 'Pick this only for an explicit request to unsubscribe, stop emailing, remove the address, or never be contacted again. Irritation, a polite no, or a request to come back later do not qualify. Nothing is sent to this person afterward.'),
	('not_required_right_now', 'The person declines for now and may be open to a later conversation.', 'Pick this when the person says the offer is not needed at this time, the timing is wrong, budget or priorities are elsewhere, or asks you to reach out later. Keep the door open: the person has not rejected future contact.'),
	('already_using_a_tool', 'The person already has a tool, vendor, or process that covers the need.', 'Pick this when the person says a current vendor, product, agency, or in-house process already does the job and they see no reason to switch. A refusal without naming an existing solution belongs under Not required right now.'),
	('wrong_contact', 'The person says they are not the right contact and names nobody else.', 'Pick this when the reply says the message reached the wrong person, or that someone else handles this, but gives no name, address, or introduction. If the reply names or copies a colleague, pick Connected to different contact.'),
	('connected_to_different_contact', 'The person points to or introduces the right contact.', 'Pick this when the reply gives another person''s name or email address, copies a colleague into the thread, or introduces the person who handles this topic. The new contact is the person to continue with.'),
	('left_company', 'The person no longer works at the company.', 'Pick this when an automatic reply, a colleague, or the person says they left the company or their address is closed. A temporary absence belongs under Out of office, even when the message mentions a long leave.'),
	('out_of_office', 'The person is away for a limited time and reads email later.', 'Pick this for vacation, leave, travel, or other temporary absence notices, often automatic and with a return date. If the notice says the person has left the company, pick Left company. No reply is needed; the sequence resumes on schedule.'),
	('other', 'The reply fits none of the other subcategories.', 'Pick this only when no other subcategory fits the latest message. Prefer a specific subcategory whenever the intent is reasonably clear. Newsletters, bounces without a clear cause, and unrelated replies end up here.')
) AS d(key, description, guidance)
WHERE s."key" = d.key
  AND (s."description" IS NULL OR btrim(s."description") = '' OR s."classification_guidance" IS NULL OR btrim(s."classification_guidance") = '');
